const giftStorageKey='minik-evren-sticker-gift-opened';
let giftShownThisVisit=false;
function stickerGiftAvailable(){return Boolean(C.startDate&&unlocked(6)&&C.chapters[6]?.pages?.length)}
function giftWasOpened(){try{return localStorage.getItem(giftStorageKey)==='yes'}catch{return false}}
function giftBox(){return `<div class="gift-surprise"><span class="eyebrow">Hikâyemizin arasına bir sürpriz sakladım</span><h2>Sana bir hediyem var ♡</h2><p>Bu küçük kutunun içinde biraz sen, biraz ben var.</p><button class="gift-open" aria-label="Hediye paketini aç"><span class="gift-box" aria-hidden="true"><span class="gift-lid"></span><span class="gift-base"></span><span class="gift-bow">♡</span><span class="gift-spark">✧</span></span><span class="gift-prompt">Açmak için dokun</span></button><div class="gift-reveal" hidden><span class="eyebrow">Sadece bize özel</span><h2>Sohbetlerimize de biraz biz serpelim.</h2><p>Gülüşümüz, minik triplerimiz, özlemimiz…<br>Hepsini 20 küçük stickerın içine sakladım.<br>Yanında olamadığım anlarda da yüzünü güldürsün diye.<br><strong>Sana özel WhatsApp sticker paketimiz, sevgilim ♡</strong></p><a class="btn" href="#stickers" data-gift-link>Hediyemizi keşfet ♡</a><a class="gift-download" href="stickers/bizim-minik-evrenimiz.wastickers" download>Paketi indir ↓</a></div></div>`}
function storyGift(){if(!stickerGiftAvailable())return '';return giftWasOpened()?`<section class="gift-return"><span>🎁</span><div><h2>Hediyemiz burada, hep seninle ♡</h2><p>20 minik stickerla sohbetlerimiz de biraz daha biz.</p></div><a class="btn" href="#stickers">Sticker köşemiz ♡</a></section>`:`<section class="gift-return"><span>🎁</span><div><h2>Sana bir hediyem var ♡</h2><p>Hikâyemizin bu sayfasına küçük bir sürpriz sakladım.</p></div><button class="btn" data-gift-show>Kutuyu aç ♡</button></section>`}
function syncStickerGift(){const available=stickerGiftAvailable();const nav=document.querySelector('[data-page="stickers"]');if(nav)nav.hidden=!available; if(available&&location.hash==='#story'&&!giftWasOpened()&&!giftShownThisVisit&&!modal.open){giftShownThisVisit=true;show(giftBox())}}
document.addEventListener('click',e=>{if(e.target.closest('[data-gift-show]')&&stickerGiftAvailable()){show(giftBox());return}const button=e.target.closest('.gift-open');if(button&&stickerGiftAvailable()&&!button.disabled){button.disabled=true;button.classList.add('opening');setTimeout(()=>{const reveal=modal.querySelector('.gift-reveal');if(!reveal)return;reveal.hidden=false;button.hidden=true;try{localStorage.setItem(giftStorageKey,'yes')}catch{}hearts();render()},850)}if(e.target.closest('[data-gift-link]'))modal.close()});
